def countStrings(S: str) -> int:
    n = len(S)
    total = n * (n - 1) // 2
    duplicates = 0
    freq = {}

    for c in S:
        freq[c] = freq.get(c, 0) + 1

    for count in freq.values():
        if count >= 2:
            duplicates += count * (count - 1) // 2

    return total - duplicates
